-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('settling-into-a-new-place', 'Settling Into a New Place', 'For anyone who has moved recently, or who still does not quite feel at home where they live. Each day is one small way to make your space your own, learn your neighborhood and find your people.', 'Transitions', 365, array['Life Transitions', 'Loneliness', 'Relationships']::text[], 1, '2026-10-29T17:00:00+00:00'::timestamptz),
  ('writing-letters-and-little-notes', 'Writing Letters and Little Notes', 'For anyone who misses the warmth of a handwritten word. Each day is one small way to write a note, card or letter, to the people around you, to faraway friends or to yourself, and let it say what matters.', 'Connection', 365, array['Relationships', 'Communication', 'Loneliness']::text[], 1, '2026-10-29T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('settling-into-a-new-place', 'writing-letters-and-little-notes');

